/// Methods of the connection itself: they open, list or authenticate sessions and
/// never belong to one, so an `Acp-Session-Id` header does not route them.
pub const CONNECTION_METHODS: &[&str] = &["initialize", "authenticate", "session/new", "session/list", "logout"];

#[must_use]
pub fn method_requires_session(method: &str) -> bool {
    SESSION_SCOPED_METHODS.contains(&method)
}

/// Is this message scoped to the CONNECTION rather than a session?
///
/// True for every `$/`-prefixed method. Cancellation is why: `$/cancel_request`
/// names a request id on the connection, so a session stream's reader has never
/// heard of it.
#[must_use]
pub fn is_connection_scoped(message: &Message) -> bool {
    message
        .method()
        .is_some_and(|m| m.starts_with("$/") || CONNECTION_METHODS.contains(&m))
}

#[must_use]
pub fn is_initialize(message: &Message) -> bool {
    matches!(message, Message::Request { method, .. } if method == "initialize")
}

/// The session a message names in its params, if any.
///
/// Object params only. Positional params cannot name a session — there is no key to
/// read — and guessing by position would route on an assumption about argument
/// order that the protocol never makes.
#[must_use]
pub fn session_from_params(message: &Message) -> Option<String> {
    if is_connection_scoped(message) {
        return None;
    }
    message
        .params()?
        .as_object()?
        .get("sessionId")?
        .as_str()
        .filter(|session| !session.is_empty())
        .map(str::to_string)
}

/// Reconcile an `Acp-Session-Id` header into a message's params.
///
/// Three cases, and the third is the one that matters:
///
/// * params do not name a session → the header's session is inserted;
/// * params name the SAME session → nothing to do;
/// * params name a DIFFERENT session → an error, never a preference. Silently
///   choosing one would route a prompt into a stranger's session, and both
///   choices are wrong because the caller has already contradicted itself.
///
/// Connection-scoped messages are returned untouched: a `$/cancel_request` must not
/// acquire a session id just because one was in the headers.
pub fn apply_session_header(message: &mut Message, session_id: &str) -> Result<(), RpcError> {
    if is_connection_scoped(message) {
        return Ok(());
    }
    if session_id.is_empty() {
        return Err(RpcError::new(INVALID_REQUEST, format!("{HEADER_SESSION_ID} is empty")));
    }
    let Some(params) = message.params_mut() else {
        return Ok(());
    };
    match params {
        Some(Value::Object(map)) => match map.get("sessionId") {
            Some(Value::String(existing)) if existing == session_id => Ok(()),
            Some(Value::String(_)) => Err(RpcError::new(
                INVALID_REQUEST,
                format!("{HEADER_SESSION_ID} does not match params.sessionId"),
            )),
            Some(_) => Err(RpcError::new(
                INVALID_REQUEST,
                "params.sessionId must be a string",
            )),
            None => {
                map.insert("sessionId".into(), serde_json::json!(session_id));
                Ok(())
            }
        },
        Some(Value::Array(_)) => Err(RpcError::new(
            INVALID_REQUEST,
            format!("{HEADER_SESSION_ID} requires object params"),
        )),
        Some(_) => Err(RpcError::new(
            INVALID_REQUEST,
            "params must be an object or an array",
        )),
        None => {
            *params = Some(serde_json::json!({ "sessionId": session_id }));
            Ok(())
        }
    }
}

/// Which stream a message belongs on.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Route {
    /// The connection-level stream.
    Connection,
    /// The stream for one session.
    Session(String),
}

/// Where a message THIS SIDE BUILT should be delivered.
///
/// Named for its direction because the unchecked version is only safe in it: a
/// message we constructed already knows its session, so there is nothing to
/// validate. For anything ARRIVING use [`resolve_route`], which enforces the rule
/// that a session-scoped method must name a session.
#[must_use]
pub fn route_outgoing(message: &Message) -> Route {
    route_unchecked(message)
}

/// The routing decision itself, without validation.
///
/// Private on purpose: an ingress caller could route a bare `session/prompt` to the
/// connection stream, which is the cross-session delivery [`resolve_route`] exists to
/// prevent.
fn route_unchecked(message: &Message) -> Route {
    if is_connection_scoped(message) {
        return Route::Connection;
    }
    session_from_params(message).map_or(Route::Connection, Route::Session)
}

/// Reconcile an optional `Acp-Session-Id` header and decide the route, REFUSING a
/// session-scoped method that names no session anywhere.
///
/// The one entry point for an incoming message. Without the refusal, a
/// `session/prompt` naming no session would route to the CONNECTION stream, which is
/// precisely the cross-session delivery the rule exists to prevent.
///
/// Order matters. The header is reconciled FIRST, so a request whose session lives
/// only in the header still satisfies the requirement; and connection-scoped messages
/// are exempt, because `$/cancel_request` names a request on the connection and has
/// no session to name.
pub fn resolve_route(
    message: &mut Message,
    header_session: Option<&str>,
) -> Result<Route, RpcError> {
    if let Some(session) = header_session {
        apply_session_header(message, session)?;
    }
    if is_connection_scoped(message) {
        return Ok(Route::Connection);
    }
    let session = session_from_params(message);
    if let Some(method) = message.method() {
        if method_requires_session(method) && session.is_none() {
            return Err(RpcError::new(
                INVALID_REQUEST,
                format!(
                    "{method} is session-scoped: supply {HEADER_SESSION_ID} or params.sessionId"
                ),
            ));
        }
    }
    Ok(session.map_or(Route::Connection, Route::Session))
}

/// Where a GROUPED reply to a batch should be delivered.
///
/// A batch's reply is one array and must stay one array, so it can only ride a
/// session stream when EVERY correlated entry agrees on that session. Any
/// disagreement sends the whole group to the connection stream — which is the
/// binding's rule, and the only one that keeps the array intact.
#[must_use]
pub fn route_for_group(messages: &[Message]) -> Route {
    let mut agreed: Option<String> = None;
    for message in messages {
        match route_unchecked(message) {
            Route::Connection => return Route::Connection,
            Route::Session(session) => match &agreed {
                Some(existing) if *existing != session => return Route::Connection,
                Some(_) => {}
                None => agreed = Some(session),
            },
        }
    }
    agreed.map_or(Route::Connection, Route::Session)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::acp::proto::CallId;

    fn request(method: &str, params: Value) -> Message {
        Message::request(CallId::number(1), method, params)
    }

    #[test]
    fn every_session_scoped_method_is_refused_without_a_session() {
        // finding_25a62af85d994d3e: connection methods ignore the header, and an empty session is none.
        let mut init = request("initialize", serde_json::json!({}));
        assert_eq!(resolve_route(&mut init, Some("s1")).unwrap(), Route::Connection);
        let mut empty = request("session/prompt", serde_json::json!({}));
        assert!(resolve_route(&mut empty, Some("")).is_err());
        let mut blank = request("session/prompt", serde_json::json!({"sessionId": ""}));
        assert!(resolve_route(&mut blank, None).is_err());
        // The rule the predicate only DESCRIBED until now. Asserted per method rather
        // than as list membership, because the failure mode is per method: one that
        // slips through routes to the connection stream and is delivered to a reader
        // that is not in that session.
        let required = [
            "session/cancel",
            "session/close",
            "session/delete",
            "session/fork",
            "session/load",
            "session/prompt",
            "session/resume",
            "session/set_config_option",
            "session/set_mode",
            "session/set_model",
            "session/update",
            "session/request_permission",
            "fs/read_text_file",
            "fs/write_text_file",
            "terminal/create",
            "terminal/output",
            "terminal/release",
            "terminal/wait_for_exit",
            "terminal/kill",
        ];
        assert_eq!(SESSION_SCOPED_METHODS.len(), required.len());
        for method in required {
            assert!(
                method_requires_session(method),
                "{method} is session-scoped in the binding"
            );
            let mut bare = request(method, serde_json::json!({}));
            let error = resolve_route(&mut bare, None)
                .expect_err(&format!("{method} must be refused without a session"));
            assert_eq!(error.code, INVALID_REQUEST);
            assert!(error.message.contains(method), "{}", error.message);

            // Named in the params: routed to that session.
            let mut in_params = request(method, serde_json::json!({ "sessionId": "s1" }));
            assert_eq!(
                resolve_route(&mut in_params, None).expect("accepted"),
                Route::Session("s1".into())
            );

            // Named only in the HEADER: reconciled, then accepted.
            let mut in_header = request(method, serde_json::json!({}));
            assert_eq!(
                resolve_route(&mut in_header, Some("s2")).expect("accepted"),
                Route::Session("s2".into())
            );
        }
    }

    #[test]
    fn methods_that_are_not_session_scoped_need_no_session() {
        for method in [
            "initialize",
            "authenticate",
            "session/new",
            "session/list",
            "logout",
        ] {
            let mut message = request(method, serde_json::json!({}));
            assert_eq!(
                resolve_route(&mut message, None).expect("accepted"),
                Route::Connection,
                "{method} establishes or enumerates rather than acting within a session"
            );
        }
        // And a connection-scoped notification is exempt even though it names none.
        let mut cancel = Message::notification("$/cancel_request", serde_json::json!({ "requestId": 1 }));
        assert_eq!(
            resolve_route(&mut cancel, Some("s1")).expect("exempt"),
            Route::Connection
        );
    }

    #[test]
    fn cancellation_stays_on_the_connection_whatever_the_headers_say() {
        // `$/cancel_request` names a request id on the CONNECTION. Routed to a
        // session stream it would reach a reader that has never heard of that id.
        let mut cancel = Message::notification("$/cancel_request", serde_json::json!({ "requestId": 1 }));
        assert!(is_connection_scoped(&cancel));
        assert_eq!(route_outgoing(&cancel), Route::Connection);

        apply_session_header(&mut cancel, "session-1").expect("untouched");
        assert_eq!(
            session_from_params(&cancel),
            None,
            "a session header must not stick to a connection-scoped message"
        );
        assert_eq!(
            cancel.params().and_then(|p| p.get("sessionId")),
            None,
            "and it must not appear in the params either"
        );
    }

    #[test]
    fn a_session_header_is_inserted_but_never_overrides() {
        // Inserted when absent.
        let mut absent = request("session/prompt", serde_json::json!({ "prompt": [] }));
        apply_session_header(&mut absent, "session-1").expect("inserted");
        assert_eq!(session_from_params(&absent).as_deref(), Some("session-1"));

        // Agreeing is a no-op.
        let mut same = request("session/prompt", serde_json::json!({ "sessionId": "session-1" }));
        apply_session_header(&mut same, "session-1").expect("agrees");

        // DISAGREEING is an error, not a preference: picking either one routes a
        // prompt into a session the caller did not mean, and it has already
        // contradicted itself so neither choice is defensible.
        let mut conflict = request("session/prompt", serde_json::json!({ "sessionId": "session-1" }));
        let error = apply_session_header(&mut conflict, "session-2").expect_err("refused");
        assert_eq!(error.code, INVALID_REQUEST);
        assert!(
            error.message.contains(HEADER_SESSION_ID),
            "{}",
            error.message
        );
        let router_err = resolve_route(&mut conflict, Some("session-2")).expect_err("refused by router");
        assert_eq!(router_err.code, INVALID_REQUEST);

        // Positional params cannot name a session, so a header cannot be applied.
        let mut positional = Message::request(CallId::number(1), "session/prompt", serde_json::json!([1, 2]));
        assert!(apply_session_header(&mut positional, "session-1").is_err());
    }

    #[test]
    fn a_grouped_reply_rides_a_session_stream_only_when_all_of_it_agrees() {
        let a = request("session/prompt", serde_json::json!({ "sessionId": "s1" }));
        let b = request("session/cancel", serde_json::json!({ "sessionId": "s1" }));
        assert_eq!(
            route_for_group(&[a.clone(), b]),
            Route::Session("s1".into())
        );

        // Mixed sessions: the array must stay intact, so it goes to the connection.
        let other = request("session/prompt", serde_json::json!({ "sessionId": "s2" }));
        assert_eq!(route_for_group(&[a.clone(), other]), Route::Connection);

        // And one connection-scoped entry pulls the whole group with it.
        let cancel = Message::notification("$/cancel_request", serde_json::json!({ "requestId": 1 }));
        assert_eq!(route_for_group(&[a, cancel]), Route::Connection);

        // An empty group has nothing to agree on.
        assert_eq!(route_for_group(&[]), Route::Connection);
    }

    #[test]
    fn initialize_is_recognised_only_as_a_request() {
        assert!(is_initialize(&request("initialize", serde_json::json!({}))));
        // A NOTIFICATION named initialize opens nothing: there is no id to answer
        // with, so no connection id could ever be returned.
        assert!(!is_initialize(&Message::notification(
            "initialize",
            serde_json::json!({})
        )));
        assert!(!is_initialize(&request("session/new", serde_json::json!({}))));
    }
}
